const SUPABASE_URL = "https://knrcyjiefwcashecmopq.supabase.co";
const SUPABASE_ANON_KEY = "sb_publishable_ehwsMOILwOBrAXsJGESBLQ_l67AxvHc";

const sb = {
  headers(token) {
    return {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${token || SUPABASE_ANON_KEY}`,
      "Content-Type": "application/json",
    };
  },
  async select(table, query = "", token) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?${query}`, { headers: this.headers(token) });
    if (!res.ok) throw new Error(`Failed to load ${table}`);
    return res.json();
  },
  async insert(table, row, token) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}`, {
      method: "POST",
      headers: { ...this.headers(token), Prefer: "return=representation" },
      body: JSON.stringify(row),
    });
    if (!res.ok) throw new Error(`Failed to add to ${table}`);
    const data = await res.json();
    return Array.isArray(data) ? data[0] : data;
  },
  async update(table, match, patch, token) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?${match}`, {
      method: "PATCH",
      headers: { ...this.headers(token), Prefer: "return=representation" },
      body: JSON.stringify(patch),
    });
    if (!res.ok) throw new Error(`Failed to update ${table}`);
    return res.json();
  },
  async remove(table, match, token) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?${match}`, {
      method: "DELETE",
      headers: this.headers(token),
    });
    if (!res.ok) throw new Error(`Failed to delete from ${table}`);
  },
  async rpc(fn, args, token) {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/${fn}`, {
      method: "POST",
      headers: this.headers(token),
      body: JSON.stringify(args),
    });
    if (!res.ok) throw new Error(`RPC ${fn} failed`);
  },
  async signIn(email, password) {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
      method: "POST",
      headers: { apikey: SUPABASE_ANON_KEY, "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error_description || data.msg || "Login failed");
    return data; // { access_token, user, ... }
  },
  async uploadImage(file, token) {
    const path = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.\-_]/g, "")}`;
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/product-images/${path}`, {
      method: "POST",
      headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${token}`, "Content-Type": file.type },
      body: file,
    });
    if (!res.ok) throw new Error("Image upload failed");
    return `${SUPABASE_URL}/storage/v1/object/public/product-images/${path}`;
  },
};

