/* ---------------- Reusable bits ---------------- */

function JerseyPatch({ num, colors, size = 120, img }) {
  if (img) {
    return (
      <div style={{ width: "100%", aspectRatio: "4/5", borderRadius: 14, overflow: "hidden", border: "1px solid #E3E8E4" }}>
        <img src={img} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </div>
    );
  }
  return (
    <div
      style={{
        width: "100%",
        aspectRatio: "4/5",
        borderRadius: 14,
        position: "relative",
        overflow: "hidden",
        background: `linear-gradient(155deg, ${colors[0]} 0%, ${colors[1]} 100%)`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        border: "1px solid rgba(255,255,255,0.15)",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "repeating-linear-gradient(115deg, rgba(255,255,255,0.06) 0 2px, transparent 2px 14px)",
        }}
      />
      {/* collar */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: "50%",
          transform: "translateX(-50%)",
          width: "34%",
          height: 22,
          background: "rgba(255,255,255,0.18)",
          borderBottomLeftRadius: 30,
          borderBottomRightRadius: 30,
        }}
      />
      <span
        style={{
          fontFamily: "Oswald, sans-serif",
          fontWeight: 700,
          fontSize: size,
          color: "rgba(255,255,255,0.9)",
          textShadow: "0 6px 24px rgba(0,0,0,0.25)",
          letterSpacing: -2,
        }}
      >
        {num}
      </span>
    </div>
  );
}

function Badge({ children, tone = "gold" }) {
  const bg = tone === "gold" ? "#9AA0A6" : tone === "green" ? "#4A4F55" : "#1A1C1E";
  return (
    <span
      style={{
        position: "absolute",
        top: 10,
        left: 10,
        background: bg,
        color: "#fff",
        fontSize: 11,
        fontWeight: 600,
        letterSpacing: 0.5,
        padding: "4px 10px",
        borderRadius: 999,
        textTransform: "uppercase",
        fontFamily: "Inter, sans-serif",
        zIndex: 2,
      }}
    >
      {children}
    </span>
  );
}

