function CartPage({ cart, updateQty, removeItem, go, shippingFee }) {
  const subtotal = cart.reduce((s, i) => s + i.price * i.qty, 0);
  const delivery = cart.length ? shippingFee : 0;
  const total = subtotal + delivery;
  return (
    <div style={{ maxWidth: 1000, margin: "0 auto", padding: "50px 24px 90px" }}>
      <h1 style={{ fontFamily: "Oswald, sans-serif", fontSize: 32, fontWeight: 600, color: "#1A1C1E", marginBottom: 30 }}>Your Cart</h1>
      {cart.length === 0 ? (
        <div style={{ textAlign: "center", padding: "60px 0" }}>
          <p style={{ fontFamily: "Inter, sans-serif", color: "#8A958E", marginBottom: 20 }}>Your cart is empty.</p>
          <button onClick={() => go("shop")} style={btnPrimary}>Continue Shopping</button>
        </div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "1.7fr 1fr", gap: 40 }} className="rj-cart">
          <div>
            {cart.map((item) => (
              <div key={item.key} style={{ display: "flex", gap: 16, padding: "18px 0", borderBottom: "1px solid #E3E8E4" }}>
                <div style={{ width: 84 }}><JerseyPatch num={item.num} colors={item.colors} size={34} img={item.images && item.images[0]} /></div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "Oswald, sans-serif", fontWeight: 600, fontSize: 16, color: "#1A1C1E" }}>{item.name}</div>
                  <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: "#8A958E", marginTop: 4 }}>Size: {item.size}</div>
                  <div style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 10 }}>
                    <div style={{ display: "flex", alignItems: "center", border: "1px solid #E3E8E4", borderRadius: 8 }}>
                      <button onClick={() => updateQty(item.key, -1)} style={qtyBtn}>−</button>
                      <span style={{ fontFamily: "Inter, sans-serif", fontWeight: 600, minWidth: 18, textAlign: "center" }}>{item.qty}</span>
                      <button onClick={() => updateQty(item.key, 1)} style={qtyBtn}>+</button>
                    </div>
                    <span onClick={() => removeItem(item.key)} style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, color: "#C0392B", cursor: "pointer" }}>Remove</span>
                  </div>
                </div>
                <div style={{ fontFamily: "Inter, sans-serif", fontWeight: 700, color: "#2C2F33" }}>{money(item.price * item.qty)}</div>
              </div>
            ))}
          </div>
          <div style={{ background: "#F4F4F5", borderRadius: 16, padding: 24, height: "fit-content" }}>
            <div style={{ fontFamily: "Oswald, sans-serif", fontWeight: 600, fontSize: 18, marginBottom: 18, color: "#1A1C1E" }}>Order Summary</div>
            <Row label="Subtotal" value={money(subtotal)} />
            <Row label="Delivery Charges" value={money(delivery)} />
            <div style={{ borderTop: "1px solid #E3E8E4", margin: "12px 0" }} />
            <Row label="Grand Total" value={money(total)} bold />
            <button onClick={() => go("checkout")} style={{ ...btnPrimary, width: "100%", marginTop: 18 }}>Proceed to Checkout</button>
          </div>
        </div>
      )}
    </div>
  );
}
function Row({ label, value, bold }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", margin: "8px 0", fontFamily: "Inter, sans-serif", fontSize: bold ? 16 : 14, fontWeight: bold ? 700 : 500, color: "#1A1C1E" }}>
      <span>{label}</span><span>{value}</span>
    </div>
  );
}

/* ---------------- Checkout Page ---------------- */

function CheckoutPage({ cart, go, placeOrder, shippingFee, discountCodes }) {
  const subtotal = cart.reduce((s, i) => s + i.price * i.qty, 0);
  const delivery = cart.length ? shippingFee : 0;
  const [form, setForm] = useState({ name: "", phone: "", address: "", area: "", landmark: "", email: "" });
  const [codeInput, setCodeInput] = useState("");
  const [applied, setApplied] = useState(null);
  const [codeError, setCodeError] = useState("");
  const valid = form.name && form.phone && form.address && form.area;

  const applyCode = () => {
    const match = discountCodes.find((d) => d.active && d.code.toLowerCase() === codeInput.trim().toLowerCase());
    if (match) { setApplied(match); setCodeError(""); }
    else { setApplied(null); setCodeError("Invalid or inactive code."); }
  };

  const discountAmt = applied ? Math.round(subtotal * (applied.percent / 100)) : 0;
  const total = subtotal - discountAmt + delivery;

  return (
    <div style={{ maxWidth: 1000, margin: "0 auto", padding: "50px 24px 90px" }}>
      <h1 style={{ fontFamily: "Oswald, sans-serif", fontSize: 32, fontWeight: 600, color: "#1A1C1E", marginBottom: 30 }}>Checkout</h1>
      <div style={{ display: "grid", gridTemplateColumns: "1.5fr 1fr", gap: 40 }} className="rj-cart">
        <div>
          <div style={{ background: "#EDEEEF", border: "1px solid #D8DADC", borderRadius: 12, padding: "14px 18px", fontFamily: "Inter, sans-serif", fontSize: 13, color: "#2C2F33", marginBottom: 24 }}>
            We currently deliver only within Karachi.
          </div>
          {[
            ["name", "Full Name"], ["phone", "Phone Number"], ["address", "Complete Karachi Address"],
            ["area", "Area"], ["landmark", "Landmark"], ["email", "Email (Optional)"],
          ].map(([key, label]) => (
            <div key={key} style={{ marginBottom: 16 }}>
              <label style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: "#1A1C1E", display: "block", marginBottom: 6 }}>{label}</label>
              <input value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} style={inputStyle} />
            </div>
          ))}
          <div style={{ marginTop: 10 }}>
            <div style={{ fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600, color: "#1A1C1E", marginBottom: 8 }}>Payment Method</div>
            <div style={{ border: "2px solid #4A4F55", background: "#EDEEEF", borderRadius: 12, padding: "14px 16px", fontFamily: "Inter, sans-serif", fontSize: 13.5, fontWeight: 600, color: "#2C2F33" }}>
              💵 Cash on Delivery — the only payment method available
            </div>
          </div>
        </div>
        <div style={{ background: "#F4F4F5", borderRadius: 16, padding: 24, height: "fit-content" }}>
          <div style={{ fontFamily: "Oswald, sans-serif", fontWeight: 600, fontSize: 18, marginBottom: 18, color: "#1A1C1E" }}>Order Summary</div>
          {cart.map((i) => <Row key={i.key} label={`${i.name} (${i.size}) × ${i.qty}`} value={money(i.price * i.qty)} />)}
          <div style={{ borderTop: "1px solid #E3E8E4", margin: "12px 0" }} />

          <label style={{ ...fieldLabel, marginTop: 0 }}>Discount Code</label>
          <div style={{ display: "flex", gap: 8 }}>
            <input value={codeInput} onChange={(e) => setCodeInput(e.target.value)} placeholder="e.g. RETRO10" style={{ ...inputStyle, flex: 1 }} />
            <button onClick={applyCode} style={{ ...adminActionBtn, padding: "0 16px" }}>Apply</button>
          </div>
          {applied && <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: "#2C2F33", marginTop: 6 }}>✓ "{applied.code}" applied — {applied.percent}% off</div>}
          {codeError && <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12, color: "#C0392B", marginTop: 6 }}>{codeError}</div>}

          <div style={{ borderTop: "1px solid #E3E8E4", margin: "14px 0" }} />
          <Row label="Subtotal" value={money(subtotal)} />
          {applied && <Row label={`Discount (${applied.percent}%)`} value={`− ${money(discountAmt)}`} />}
          <Row label="Delivery Charges" value={money(delivery)} />
          <div style={{ borderTop: "1px solid #E3E8E4", margin: "12px 0" }} />
          <Row label="Grand Total" value={money(total)} bold />
          <button
            disabled={!valid || cart.length === 0}
            onClick={() => placeOrder(form, { subtotal, delivery, discount: discountAmt, code: applied ? applied.code : null, total })}
            style={{ ...btnPrimary, width: "100%", marginTop: 18, opacity: valid && cart.length ? 1 : 0.5, cursor: valid && cart.length ? "pointer" : "not-allowed" }}
          >Place Order</button>
        </div>
      </div>
    </div>
  );
}
const inputStyle = { width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #E3E8E4", fontFamily: "Inter, sans-serif", fontSize: 14, outline: "none", boxSizing: "border-box" };

