function AdminPage({
  products, addProduct, updateProduct, deleteProduct,
  categories, addCategory, deleteCategory,
  orders, updateOrderStatus,
  discountCodes, addDiscount, deleteDiscount, toggleDiscount,
  settings, updateSettings,
  adminAuthed, adminLogin, adminLogout,
  isConfigured, dbConnected, dbError, accessToken,
}) {
  const [tab, setTab] = useState("dashboard");
  if (!adminAuthed) return <AdminLogin onLogin={adminLogin} isConfigured={isConfigured} />;

  const tabs = [
    ["dashboard", "Dashboard"], ["products", "Products"], ["orders", "Orders"],
    ["categories", "Categories"], ["discounts", "Discount Codes"], ["settings", "Settings"],
  ];

  return (
    <div style={{ maxWidth: 1240, margin: "0 auto", padding: "40px 24px 100px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 14, flexWrap: "wrap", gap: 12 }}>
        <div>
          <div style={{ fontFamily: "Inter, sans-serif", fontSize: 12.5, fontWeight: 600, color: "#4A4F55", letterSpacing: 2, textTransform: "uppercase" }}>{settings.storeName}</div>
          <h1 style={{ fontFamily: "Oswald, sans-serif", fontSize: 30, fontWeight: 600, color: "#1A1C1E", margin: "6px 0 0" }}>Admin Dashboard</h1>
        </div>
        <button onClick={adminLogout} style={adminActionBtn}>Log Out</button>
      </div>

      <div style={{
        display: "inline-flex", alignItems: "center", gap: 6, fontFamily: "Inter, sans-serif", fontSize: 12,
        color: isConfigured && dbConnected ? "#2C6B3F" : "#8A958E", marginBottom: 20,
      }}>
        <span style={{ width: 7, height: 7, borderRadius: "50%", background: isConfigured && dbConnected ? "#2C6B3F" : "#C9A227" }} />
        {isConfigured && dbConnected ? "Connected to Supabase — changes save to your database" : isConfigured ? (dbError || "Could not reach Supabase — using local demo data") : "Supabase not configured — using local demo data"}
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 26, flexWrap: "wrap", borderBottom: "1px solid #E3E8E4", paddingBottom: 14 }}>
        {tabs.map(([key, label]) => (
          <button key={key} onClick={() => setTab(key)} style={{
            padding: "9px 18px", borderRadius: 999, cursor: "pointer", fontFamily: "Inter, sans-serif", fontSize: 13, fontWeight: 600,
            border: tab === key ? "1px solid #4A4F55" : "1px solid #E3E8E4",
            background: tab === key ? "#4A4F55" : "#fff", color: tab === key ? "#fff" : "#1A1C1E",
          }}>{label}</button>
        ))}
      </div>

      {tab === "dashboard" && <AdminDashboardTab products={products} orders={orders} />}
      {tab === "products" && <AdminProductsTab products={products} addProduct={addProduct} updateProduct={updateProduct} deleteProduct={deleteProduct} categories={categories} accessToken={accessToken} isConfigured={isConfigured} />}
      {tab === "orders" && <AdminOrdersTab orders={orders} updateOrderStatus={updateOrderStatus} />}
      {tab === "categories" && <AdminCategoriesTab categories={categories} addCategory={addCategory} deleteCategory={deleteCategory} products={products} />}
      {tab === "discounts" && <AdminDiscountsTab discountCodes={discountCodes} addDiscount={addDiscount} deleteDiscount={deleteDiscount} toggleDiscount={toggleDiscount} />}
      {tab === "settings" && <AdminSettingsTab settings={settings} updateSettings={updateSettings} />}
    </div>
  );
}
