function BackToTop({ show }) {
  if (!show) return null;
  return (
    <button onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} style={{
      position: "fixed", bottom: 24, left: 24, zIndex: 60, width: 44, height: 44, borderRadius: "50%",
      background: "#1A1C1E", color: "#fff", border: "none", cursor: "pointer", fontSize: 18,
      boxShadow: "0 10px 24px -6px rgba(0,0,0,0.35)",
    }}>↑</button>
  );
}

function ScrollProgress() {
  const [p, setP] = useState(0);
  useEffect(() => {
    const onScroll = () => {
      const h = document.documentElement;
      const scrolled = (h.scrollTop) / (h.scrollHeight - h.clientHeight) * 100;
      setP(scrolled || 0);
    };
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return <div style={{ position: "fixed", top: 0, left: 0, height: 3, width: `${p}%`, background: "#4A4F55", zIndex: 100, transition: "width .1s" }} />;
}

/* ---------------- App ---------------- */

export default function App() {
  const [page, setPage] = useState("home");
  const [products, setProducts] = useState(INITIAL_PRODUCTS);
  const [activeProduct, setActiveProduct] = useState(INITIAL_PRODUCTS[0]);
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [search, setSearch] = useState("");
  const [orderNum, setOrderNum] = useState("RJ10234");
  const [showTop, setShowTop] = useState(false);
  const [loading, setLoading] = useState(true);
  const [categories, setCategories] = useState(DEFAULT_CATEGORIES);
  const [orders, setOrders] = useState(SEED_ORDERS);
  const [discountCodes, setDiscountCodes] = useState(SEED_DISCOUNTS);
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [adminAuthed, setAdminAuthed] = useState(false);
  const [accessToken, setAccessToken] = useState(null);
  const [dbConnected, setDbConnected] = useState(false);
  const [dbError, setDbError] = useState("");

  const isConfigured = SUPABASE_ANON_KEY && SUPABASE_ANON_KEY !== "PASTE_YOUR_ANON_PUBLIC_KEY_HERE";

  // Initial load from Supabase (falls back to mock data if not configured / offline)
  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 700);
    if (!isConfigured) return () => clearTimeout(t);
    (async () => {
      try {
        const [prodRows, catRows, discRows, settingsRows] = await Promise.all([
          sb.select("products", "select=*&order=created_at.desc"),
          sb.select("categories", "select=name&order=name.asc"),
          sb.select("discount_codes", "select=*"),
          sb.select("settings", "select=*&id=eq.1"),
        ]);
        const mappedProducts = prodRows.map(fromDbProduct);
        setProducts(mappedProducts);
        if (mappedProducts[0]) setActiveProduct(mappedProducts[0]);
        if (catRows.length) setCategories(catRows.map((c) => c.name));
        if (discRows.length) setDiscountCodes(discRows);
        if (settingsRows[0]) setSettings(fromDbSettings(settingsRows[0]));
        setDbConnected(true);
      } catch (e) {
        setDbError(e.message || "Could not reach Supabase. Showing local demo data instead.");
      }
    })();
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const onScroll = () => setShowTop(window.scrollY > 500);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const go = (key, product) => {
    if (product) setActiveProduct(product);
    setPage(key);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };
  const openProduct = (p) => go("product", p);

  const addToCart = (p, size, qty = 1) => {
    setCart((prev) => {
      const key = `${p.id}-${size}`;
      const existing = prev.find((i) => i.key === key);
      if (existing) return prev.map((i) => (i.key === key ? { ...i, qty: i.qty + qty } : i));
      return [...prev, { ...p, size, qty, key }];
    });
  };
  const updateQty = (key, delta) => {
    setCart((prev) => prev.map((i) => (i.key === key ? { ...i, qty: Math.max(1, i.qty + delta) } : i)).filter(Boolean));
  };
  const removeItem = (key) => setCart((prev) => prev.filter((i) => i.key !== key));
  const toggleWishlist = (id) => setWishlist((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]));

  const placeOrder = async (form, totals) => {
    const num = `RJ${Math.floor(10000 + Math.random() * 89999)}`;
    const newOrder = {
      id: num,
      date: new Date().toISOString().slice(0, 10),
      status: "Pending",
      customer: { name: form.name, phone: form.phone, address: form.address, area: form.area, landmark: form.landmark },
      items: cart.map((i) => ({ name: i.name, size: i.size, qty: i.qty, price: i.price })),
      subtotal: totals.subtotal, discount: totals.discount, code: totals.code, delivery: totals.delivery, total: totals.total,
    };

    if (isConfigured && dbConnected) {
      try {
        await sb.insert("orders", toDbOrder(newOrder));
        await Promise.all(cart.map((c) => sb.rpc("decrement_stock", { p_id: c.id, p_qty: c.qty })));
      } catch (e) {
        console.error("Order sync failed, saved locally only:", e.message);
      }
    }

    setOrders((prev) => [newOrder, ...prev]);
    setProducts((prev) => prev.map((p) => {
      const inCart = cart.find((c) => c.id === p.id);
      return inCart ? { ...p, stock: Math.max(0, p.stock - inCart.qty) } : p;
    }));
    setOrderNum(num);
    setCart([]);
    go("confirmation");
  };

  const addProduct = async (payload) => {
    if (isConfigured && accessToken) {
      try {
        const row = await sb.insert("products", toDbProduct(payload), accessToken);
        setProducts((prev) => [fromDbProduct(row), ...prev]);
        return;
      } catch (e) { console.error(e.message); }
    }
    setProducts((prev) => [{ id: Date.now(), ...payload }, ...prev]);
  };
  const updateProduct = async (id, payload) => {
    if (isConfigured && accessToken) {
      try { await sb.update("products", `id=eq.${id}`, toDbProduct(payload), accessToken); }
      catch (e) { console.error(e.message); }
    }
    setProducts((prev) => prev.map((p) => (p.id === id ? { ...p, ...payload } : p)));
    setActiveProduct((prev) => (prev && prev.id === id ? { ...prev, ...payload } : prev));
  };
  const deleteProduct = async (id) => {
    if (isConfigured && accessToken) {
      try { await sb.remove("products", `id=eq.${id}`, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setProducts((prev) => prev.filter((p) => p.id !== id));
    setWishlist((prev) => prev.filter((x) => x !== id));
  };

  const addCategory = async (name) => {
    if (isConfigured && accessToken) {
      try { await sb.insert("categories", { name }, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setCategories((prev) => (prev.includes(name) ? prev : [...prev, name]));
  };
  const deleteCategory = async (name) => {
    if (isConfigured && accessToken) {
      try { await sb.remove("categories", `name=eq.${encodeURIComponent(name)}`, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setCategories((prev) => prev.filter((c) => c !== name));
  };

  const updateOrderStatus = async (id, status) => {
    if (isConfigured && accessToken) {
      try { await sb.update("orders", `id=eq.${id}`, { status }, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setOrders((prev) => prev.map((o) => (o.id === id ? { ...o, status } : o)));
  };

  const addDiscount = async (code, percent) => {
    if (isConfigured && accessToken) {
      try { await sb.insert("discount_codes", { code, percent, active: true }, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setDiscountCodes((prev) => [{ code, percent, active: true }, ...prev]);
  };
  const deleteDiscount = async (code) => {
    if (isConfigured && accessToken) {
      try { await sb.remove("discount_codes", `code=eq.${encodeURIComponent(code)}`, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setDiscountCodes((prev) => prev.filter((d) => d.code !== code));
  };
  const toggleDiscount = async (code) => {
    const current = discountCodes.find((d) => d.code === code);
    if (isConfigured && accessToken && current) {
      try { await sb.update("discount_codes", `code=eq.${encodeURIComponent(code)}`, { active: !current.active }, accessToken); }
      catch (e) { console.error(e.message); }
    }
    setDiscountCodes((prev) => prev.map((d) => (d.code === code ? { ...d, active: !d.active } : d)));
  };

  const updateSettings = async (patch) => {
    if (isConfigured && accessToken) {
      try { await sb.update("settings", "id=eq.1", toDbSettings({ ...settings, ...patch }), accessToken); }
      catch (e) { console.error(e.message); }
    }
    setSettings((prev) => ({ ...prev, ...patch }));
  };

  const adminLogin = async (email, password) => {
    if (!isConfigured) { setAdminAuthed(true); return; } // demo mode fallback
    const data = await sb.signIn(email, password);
    setAccessToken(data.access_token);
    setAdminAuthed(true);
    // reload admin-only data (orders) now that we're authenticated
    try {
      const orderRows = await sb.select("orders", "select=*&order=created_at.desc", data.access_token);
      setOrders(orderRows.map(fromDbOrder));
    } catch (e) { console.error(e.message); }
  };
  const adminLogout = () => { setAdminAuthed(false); setAccessToken(null); };

  return (
    <div style={{ fontFamily: "Inter, sans-serif", background: "#fff", minHeight: "100vh" }}>
      <style>{`
        @import url('${FONT_LINK}');
        * { box-sizing: border-box; }
        body { margin: 0; }
        details > summary { list-style: none; }
        details > summary::-webkit-details-marker { display: none; }
        .rj-hero-btn {
          transition: transform .3s cubic-bezier(.2,.8,.2,1), box-shadow .3s ease, background .3s ease, border-color .3s ease;
          will-change: transform;
        }
        .rj-hero-btn-primary:hover {
          background: #6B7076 !important;
          transform: translateY(-3px) scale(1.03);
          box-shadow: 0 16px 34px -10px rgba(0,0,0,0.45);
        }
        .rj-hero-btn-primary:active {
          transform: translateY(-1px) scale(0.98);
        }
        .rj-hero-btn-ghost:hover {
          background: rgba(255,255,255,0.24) !important;
          border-color: rgba(255,255,255,0.8) !important;
          transform: translateY(-3px) scale(1.03);
        }
        .rj-hero-btn-ghost:active {
          transform: translateY(-1px) scale(0.98);
        }
        @keyframes rjFadeUp {
          from { opacity: 0; transform: translateY(28px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .rj-page-enter {
          animation: rjFadeUp .7s cubic-bezier(.2,.8,.2,1) both;
        }
        @media (max-width: 900px) {
          .rj-nav { display: none !important; }
          .rj-collections, .rj-grid, .rj-why { grid-template-columns: repeat(2, 1fr) !important; }
          .rj-footer-grid { grid-template-columns: 1fr 1fr !important; }
          .rj-product, .rj-cart { grid-template-columns: 1fr !important; }
          .rj-insta { grid-template-columns: repeat(3, 1fr) !important; }
        }
        @media (max-width: 520px) {
          .rj-collections, .rj-grid, .rj-why { grid-template-columns: 1fr !important; }
          .rj-footer-grid { grid-template-columns: 1fr !important; }
        }
      `}</style>

      {loading && (
        <div style={{ position: "fixed", inset: 0, background: "#1A1C1E", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontFamily: "Oswald, sans-serif", color: "#fff", fontSize: 26, fontWeight: 700, letterSpacing: 1 }}>
            <span style={{ color: "#4A4F55" }}>Jersey</span> Collection
          </div>
        </div>
      )}

      <ScrollProgress />
      <Header page={page} go={go} cartCount={cart.reduce((s, i) => s + i.qty, 0)} wishlistCount={wishlist.length} search={search} setSearch={setSearch} />

      <div key={page} className="rj-page-enter">
        {page === "home" && <HomePage go={go} openProduct={openProduct} wishlist={wishlist} toggleWishlist={toggleWishlist} addToCart={addToCart} products={products} />}
        {page === "shop" && <ShopPage openProduct={openProduct} wishlist={wishlist} toggleWishlist={toggleWishlist} addToCart={addToCart} search={search} products={products} categories={categories} />}
        {page === "product" && <ProductPage product={activeProduct} addToCart={addToCart} go={go} wishlist={wishlist} toggleWishlist={toggleWishlist} products={products} />}
        {page === "cart" && <CartPage cart={cart} updateQty={updateQty} removeItem={removeItem} go={go} shippingFee={settings.shippingFee} />}
        {page === "checkout" && <CheckoutPage cart={cart} go={go} placeOrder={placeOrder} shippingFee={settings.shippingFee} discountCodes={discountCodes} />}
        {page === "confirmation" && <ConfirmationPage orderNum={orderNum} go={go} />}
        {page === "about" && <AboutPage />}
        {page === "contact" && <ContactPage />}
        {page === "wishlist" && <WishlistPage wishlist={wishlist} openProduct={openProduct} toggleWishlist={toggleWishlist} addToCart={addToCart} go={go} products={products} />}
        {page === "admin" && <AdminPage
          products={products} addProduct={addProduct} updateProduct={updateProduct} deleteProduct={deleteProduct}
          categories={categories} addCategory={addCategory} deleteCategory={deleteCategory}
          orders={orders} updateOrderStatus={updateOrderStatus}
          discountCodes={discountCodes} addDiscount={addDiscount} deleteDiscount={deleteDiscount} toggleDiscount={toggleDiscount}
          settings={settings} updateSettings={updateSettings}
          adminAuthed={adminAuthed} adminLogin={adminLogin} adminLogout={adminLogout}
          isConfigured={isConfigured} dbConnected={dbConnected} dbError={dbError} accessToken={accessToken}
        />}
      </div>

      <Footer go={go} />
      <WhatsAppButton />
      <BackToTop show={showTop} />
    </div>
  );
}
